  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Atazanavir, a peptidomimetic HIV protease inhibitor with carbamate groups and high molecular weight, has 69% oral bioavailability under fasting conditions, demonstrating that this structural class can exceed the 20% threshold despite unfavorable physicochemical properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Amprenavir, sharing the hydroxyethylene core and carbamate functionality, is orally bioavailable at >70% in humans, supporting good absorption for the query's scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Darunavir, a close analogue with a carbamate and similar core, has 37% oral bioavailability when given alone, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "KNI-272, a peptidomimetic protease inhibitor with thiazole/thioproline and hydroxyethylene core, achieved ~55% absolute oral bioavailability in fasting patients, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lopinavir, the highest-similarity analogue, has low oral bioavailability due to CYP3A/P-gp and poor solubility; this is the strongest evidence for low, but the query's carbamate and thiazole substituents align more closely with high-bioavailability analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F>=20%). The query is ritonavir, a peptidomimetic HIV protease inhibitor with two thiazoles, a urea, and a carbamate. Although the closest analogue lopinavir is low-bioavailability, multiple structurally related protease inhibitors (atazanavir 69% fasting, amprenavir >70%, darunavir 37%, KNI-272 ~55% fasting) demonstrate F>=20%, and the low-confidence physicochemical prior is outweighed by this transferable experimental evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (ritonavir) is included in the provided evidence set.",
    "Lopinavir, the closest analogue, is low-bioavailability; its exact F relative to the 20% threshold is not numerically specified.",
    "Fasted-state data are available for some analogues but not all; formulation and dose effects may influence F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

